// Generated by `cargo rullst add browser-tests`; this file belongs to the
// application. It opens every HTML page of the PAGES list in
// src/security_tests.rs in Chromium, Firefox and WebKit, with the Playwright
// and axe-core versions pinned by package-lock.json, and fails on:
//
// - a console error, an uncaught page error or a failed same-origin request;
// - a Content-Security-Policy violation;
// - an axe-core violation of serious or critical impact (moderate and minor
//   ones are printed as notes), in both colour schemes when a stylesheet has
//   a `prefers-color-scheme: dark` rule.
//
//   npm ci --prefix tests/browser
//   node tests/browser/node_modules/playwright/cli.js install --with-deps chromium firefox webkit
//   cargo run                      # in another terminal: the application on port 3000
//   node tests/browser/pages.mjs   # [--base-url URL] [--browsers chromium,firefox,webkit]
//
// The report is written to tests/browser/results/report.json.
// Guide: https://rullst.github.io/Rullst/book/testing-your-app.html
import { chromium, firefox, webkit } from "playwright";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";

const HERE = dirname(fileURLToPath(import.meta.url));
const PAGE_LIST = resolve(HERE, "..", "..", "src", "security_tests.rs");
const RESULTS = join(HERE, "results");
const ENGINES = { chromium, firefox, webkit };
const BLOCKING_IMPACTS = new Set(["serious", "critical"]);
const require = createRequire(import.meta.url);
const AXE_SOURCE = await readFile(require.resolve("axe-core/axe.min.js"), "utf8");

const { values: options } = parseArgs({
  options: {
    "base-url": { type: "string", default: "http://127.0.0.1:3000" },
    browsers: { type: "string", default: "chromium,firefox,webkit" },
  },
});
const base = new URL(options["base-url"]);
const browsers = options.browsers.split(",").map(name => name.trim()).filter(Boolean);
for (const name of browsers) {
  if (!ENGINES[name]) throw new Error(`unknown browser "${name}" (chromium, firefox or webkit)`);
}

// The ("/path", status) entries of `const PAGES` in src/security_tests.rs;
// commented-out entries are skipped.
function parsePages(source) {
  const list = source.match(/const PAGES: &\[\(&str, u16\)\] = &\[([\s\S]*?)\];/);
  if (!list) return [];
  const code = list[1].split("\n").map(line => line.replace(/\/\/.*$/, "")).join("\n");
  return [...code.matchAll(/\(\s*"([^"]+)"\s*,\s*(\d{3})\s*\)/g)]
    .map(([, path, status]) => ({ path, status: Number(status) }));
}

async function pageList() {
  const source = await readFile(PAGE_LIST, "utf8").catch(() => "");
  const pages = parsePages(source);
  if (pages.length > 0) return pages;
  console.warn("No PAGES list in src/security_tests.rs: only / is visited.");
  return [{ path: "/", status: 200 }];
}

// Runs in the page: whether a stylesheet applies rules to the dark scheme.
function hasDarkScheme() {
  const dark = media => /prefers-color-scheme:\s*dark/i.test(media?.mediaText ?? "");
  const visit = rules => [...rules].some(rule =>
    dark(rule.media) || (rule.styleSheet && visit(rule.styleSheet.cssRules)) || (rule.cssRules && visit(rule.cssRules)));
  return [...document.styleSheets].some(sheet => {
    try { return dark(sheet.media) || visit(sheet.cssRules); } catch { return false; }
  });
}

class Run {
  constructor(name) {
    this.name = name;
    this.current = "(start)";
    this.failures = [];
    this.notes = [];
    this.visits = 0;
  }

  fail(message) {
    this.failures.push(`${this.name} ${this.current}: ${message}`);
  }

  async open() {
    this.browser = await ENGINES[this.name].launch();
    // No bypassCSP: the application's own Content-Security-Policy applies.
    this.context = await this.browser.newContext({ baseURL: base.href, colorScheme: "light" });
    this.context.setDefaultTimeout(60_000);
    await this.context.exposeBinding("__rullstCspViolation", (_source, violation) =>
      this.fail(`CSP blocked ${violation.directive} ${violation.blocked || "inline"}`));
    await this.context.addInitScript(() => {
      document.addEventListener("securitypolicyviolation", event => {
        window.__rullstCspViolation({ directive: event.effectiveDirective, blocked: event.blockedURI });
      }, true);
    });
    this.page = await this.context.newPage();
    this.page.on("console", message => {
      if (message.type() === "error") this.fail(`console error: ${message.text().slice(0, 200)}`);
    });
    this.page.on("pageerror", error => this.fail(`uncaught error: ${String(error.message).slice(0, 200)}`));
    this.page.on("response", response => {
      const url = new URL(response.url());
      if (url.origin === base.origin && response.status() >= 400 && !this.expectedError(url.pathname)) {
        this.fail(`${response.status()} for ${response.request().method()} ${url.pathname}`);
      }
    });
  }

  expectedError(path) {
    return this.entry?.path === path && this.entry.status >= 400;
  }

  async audit(scheme) {
    await this.page.evaluate(AXE_SOURCE);
    const violations = await this.page.evaluate(async () => {
      const result = await window.axe.run(document, { resultTypes: ["violations"] });
      return result.violations.map(rule => ({
        id: rule.id, impact: rule.impact, help: rule.help,
        targets: rule.nodes.slice(0, 3).map(node => node.target.join(" ")),
      }));
    });
    for (const rule of violations) {
      const line = `${this.name} ${this.current} (${scheme}): axe ${rule.impact} ${rule.id}: ${rule.help} at ${rule.targets.join("; ")}`;
      (BLOCKING_IMPACTS.has(rule.impact) ? this.failures : this.notes).push(line);
    }
  }

  async visit(entry) {
    this.entry = entry;
    this.current = entry.path;
    // Only HTML pages are opened; /health and other JSON routes are skipped.
    const probe = await this.context.request.get(entry.path);
    if (!(probe.headers()["content-type"] ?? "").includes("text/html")) return;
    const response = await this.page.goto(entry.path, { waitUntil: "load" });
    if (!response) {
      this.fail("no response");
      return;
    }
    if (entry.status < 400 && !response.ok()) this.fail(`answered ${response.status()}`);
    // Scripts that run after load report their errors here too.
    await this.page.waitForTimeout(300);
    this.visits += 1;
    await this.audit("light");
    if (await this.page.evaluate(hasDarkScheme)) {
      await this.page.emulateMedia({ colorScheme: "dark" });
      await this.audit("dark");
      await this.page.emulateMedia({ colorScheme: "light" });
    }
  }

  async close() {
    await this.browser?.close().catch(() => {});
  }
}

const pages = await pageList();
const runs = [];
for (const name of browsers) {
  const run = new Run(name);
  runs.push(run);
  try {
    await run.open();
    for (const entry of pages) await run.visit(entry);
    if (run.visits === 0) run.fail("no HTML page in PAGES");
  } catch (error) {
    run.fail(String(error?.message ?? error).split("\n")[0]);
  } finally {
    await run.close();
  }
}

const failures = [...new Set(runs.flatMap(run => run.failures))];
const notes = [...new Set(runs.flatMap(run => run.notes))];
await mkdir(RESULTS, { recursive: true });
await writeFile(join(RESULTS, "report.json"), JSON.stringify({
  base_url: base.href,
  pages,
  browsers: runs.map(run => ({ browser: run.name, visits: run.visits, failures: run.failures, notes: run.notes })),
}, null, 2));
for (const note of notes) console.log(`note: ${note}`);
for (const failure of failures) console.error(`FAIL ${failure}`);
const visits = runs.map(run => `${run.name} ${run.visits}`).join(", ");
console.log(`${pages.length} listed page(s); HTML visits: ${visits}; ${failures.length} failure(s), ${notes.length} note(s).`);
process.exitCode = failures.length > 0 ? 1 : 0;
